package com.gymflow.app;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class SettingsActivity extends AppCompatActivity {
 private String gymId="";
 @Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout r=Ui.page(this);s.addView(r);Ui.backHeader(this,r,"Configuración");EditText gym=Ui.input(this,"Nombre del gimnasio");r.addView(gym);EditText phone=Ui.input(this,"Teléfono");r.addView(phone);EditText address=Ui.input(this,"Dirección");r.addView(address);TextView state=Ui.subtitle(this,"Cargando configuración online...");r.addView(state);Button save=Ui.button(this,"Guardar configuración");r.addView(save);Cloud.get(this,"gf_gyms","select=id,name,phone,address&owner_id=eq."+Session.uid(this),(c,b)->{try{JSONArray a=new JSONArray(b);if(a.length()>0){JSONObject o=a.getJSONObject(0);gymId=o.optString("id");gym.setText(o.optString("name"));phone.setText(o.optString("phone"));address.setText(o.optString("address"));state.setText("Configuración sincronizada.");}}catch(Exception e){state.setText("No se pudo cargar.");}});save.setOnClickListener(v->{try{JSONObject o=new JSONObject();o.put("name",gym.getText().toString().trim());o.put("phone",phone.getText().toString().trim());o.put("address",address.getText().toString().trim());if(gymId.isEmpty()){o.put("owner_id",Session.uid(this));Cloud.post(this,"gf_gyms",o,(c,b)->state.setText(c>=200&&c<300?"Guardado.":Cloud.err(b)));}else Cloud.patch(this,"gf_gyms","id=eq."+gymId,o,(c,b)->state.setText(c>=200&&c<300?"Guardado.":Cloud.err(b)));}catch(Exception e){state.setText(e.toString());}});setContentView(s);}
}
